33	 * The claims on a sheet: listed newest first, added to a person and edited one at a time. A claim
34	 * added with no date takes the entry date while one is set, else the sheet's today (an edit with none, the sheet's today). Its due-by is fixed when it is added: the terms-th business day
35	 * after its date (skipping weekends and the sheet's holidays then), with its person's own terms, else the terms in force on that date of its person's grade then (else the
36	 * sheet's terms in force on it); it does not
37	 * move when its date or the terms change later. A claim is added as DRAFT and moves through its statuses
38	 * as {@link ClaimStatus} allows; a change it does not allow is refused. Settling or approving a claim
39	 * gives it the sheet's next number (or, while the sheet numbers by period, the next within its period),
40	 * which it keeps when voided and is never given again; an OPEN, PENDING or REVIEW claim has none (one
41	 * numbered when opened, before numbering moved to settlement, keeps its number). Only a DRAFT claim
42	 * can be edited; an OPEN one is changed by voiding it and adding a new one. Settling it
43	 * fixes its due at its figure (the due bound by a statement, else its person's grade rate of the
44	 * moment on the claim's date) with its late charge of the moment frozen in; with no figure it
45	 * stays live. A steward can re-settle a SETTLED claim at the figure it would have today as an open claim
46	 * bound by no statement, or void it within 7 days of its settlement: its frozen figure leaves every total
47	 * and it keeps its number. The user who opened a claim cannot settle it, and a clerk cannot settle one whose
48	 * due is above the sheet's clerk limit (a steward can). A claim with no proofs whose due is above the proof threshold
49	 * in force on its date cannot be settled or approved by anyone, and one with an empty note whose due is above the
50	 * note threshold in force on its date cannot be opened. No claim whose due-by falls inside a closed period can
51	 * be added, edited (to or from such a date), opened, settled, re-settled or voided. No claim can be added
52	 * or edited to a date after its person's retirement date. A claim with a negative amount is a
53	 * correction: it must name, by number, a SETTLED claim of the same person; only a correction may name one.
54	 * A claim whose due is above the review threshold in force on its date goes to REVIEW when opened, with no
55	 * number, until a steward reviews it ({@link #review}).
56	 * A steward can re-date an OPEN or PENDING claim ({@link #redate}), and set a DRAFT, OPEN or PENDING
57	 * claim's due-by directly ({@link #setDueBy}). A DRAFT claim can be deleted, and
58	 * restored to DRAFT on the same sheet's today ({@link #delete}, {@link #restore}).
59	 */
60	@Service
61	public class ClaimService {
62	
63	    /** How many days after its settlement a steward may still void a SETTLED claim. */
64	    static final int VOID_SETTLED_DAYS = 7;
65	
66	    private final ClaimRepository claims;
67	    private final PersonRepository people;
68	    private final RateService rates;
69	    private final SheetService sheets;
70	    private final RollupService rollup;
71	    private final PeriodRepository periods;
72	    private final SettingService settings;
73	    private final PersonWatchRepository watches;
74	    private final HolidayService holidays;
75	    private final ClaimTagRepository tags;
76	    private final VoidReasonService voidReasons;
77	    private final Audit audit;
78	
79	    public ClaimService(ClaimRepository claims, PersonRepository people, RateService rates, SheetService sheets,
80	            RollupService rollup, PeriodRepository periods, SettingService settings, PersonWatchRepository watches,
81	            HolidayService holidays, ClaimTagRepository tags, VoidReasonService voidReasons, Audit audit) {
82	        this.voidReasons = voidReasons;
83	        this.tags = tags;
84	        this.watches = watches;
85	        this.holidays = holidays;
86	        this.settings = settings;
87	        this.periods = periods;
88	        this.claims = claims;
89	        this.people = people;
90	        this.rates = rates;
91	        this.sheets = sheets;
92	        this.rollup = rollup;
93	        this.audit = audit;
94	    }
95	
96	    @Transactional(readOnly = true)
97	    public List<Claim> list(String sheetId) {
98	        return claims.findBySheetIdOrderByListedDesc(sheetId);
99	    }
100	
101	    /** Every tag ever used on a claim of the sheet, sorted. */
102	    @Transactional(readOnly = true)
103	    public List<String> tags(String sheetId) {
104	        return tags.findBySheetIdOrderByTagAsc(sheetId).stream().map(ClaimTag::getTag).toList();
105	    }
106	
107	    @Transactional
108	    public Claim add(String sheetId, String user, Long personId, BigDecimal amount, LocalDate date, String note,
109	            String corrects) {
110	        return add(sheetId, user, personId, amount, date, note, corrects, null);
111	    }
112	
113	    @Transactional
114	    public Claim add(String sheetId, String user, Long personId, BigDecimal amount, LocalDate date, String note,
115	            String corrects, String ref) {
116	        return add(sheetId, user, personId, amount, date, note, corrects, ref, List.of());
117	    }
118	
119	    /**
120	     * Add a claim carrying an external reference (null: none) and tags (as {@link Claim#tagsOf} reads them);
121	     * a reference already on the sheet is refused.
122	     */
123	    @Transactional
124	    public Claim add(String sheetId, String user, Long personId, BigDecimal amount, LocalDate date, String note,
125	            String corrects, String ref, List<String> tagged) {
126	        // The snapshot locks the sheet first, so the person is read as retired by any retirement before.
127	        RollupService.Snapshot before = rollup.snapshot(sheetId);
128	        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
129	        LocalDate on = dateOrEntryDate(sheetId, date);
130	        int terms = termsOf(sheetId, person, sheets.today(sheetId));
131	        LocalDate dueBy = holidays.businessDaysAfter(sheetId, on, terms);
132	        refuseIfClosed(sheetId, dueBy);
133	        if (!person.mayClaimOn(on)) throw new PersonRetiredException();
134	        refuseUnlessCorrects(sheetId, personId, null, amount, corrects);
135	        refuseIfRefUsed(sheetId, null, ref);
136	        Claim draft = new Claim(sheetId, personId, amount, on, note, dueBy, terms);
137	        draft.setCorrects(corrects);
138	        draft.setRef(ref);
139	        draft.setTags(tagged);
140	        draft.setLateEntry(periods.softClosedOn(sheetId, dueBy));
141	        Claim claim = claims.saveAndFlush(draft);
142	        logStatus(sheetId, user, person, claim);
143	        claim = claims.saveAndFlush(claim);
144	        record("CLAIM_ADDED", sheetId, user, person, claim, claim.getNumber(),
145	                (claim.getRef() != null ? " ref=" + claim.getRef() : "")
146	                + (claim.getTags().isEmpty() ? "" : " tags=" + String.join(",", claim.getTags())));
147	        keepTags(sheetId, claim);
148	        if (claim.isLateEntry()) record("LATE_ENTRY", sheetId, user, person, claim);
149	        rollup.recordChanges(sheetId, user, before);
150	        return claim;
151	    }
152	
153	    @Transactional
154	    public Claim edit(String sheetId, String user, Long id, BigDecimal amount, LocalDate date, String note,
155	            String corrects, String ref, List<String> tagged) {
156	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
157	        if (claim.getStatus() != ClaimStatus.DRAFT) {
158	            throw new ClaimStatusRefusedException();
159	        }
160	        RollupService.Snapshot before = rollup.snapshot(sheetId);
161	        if (claim.isLockedAgainst(user)) throw new ClaimLockedException();
162	        LocalDate on = dateOrToday(sheetId, date);
163	        refuseIfClosed(sheetId, claim.getDueBy());
164	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
165	        if (!person.mayClaimOn(on)) throw new PersonRetiredException();
166	        refuseUnlessCorrects(sheetId, person.getId(), claim.getId(), amount, corrects);
167	        refuseIfRefUsed(sheetId, claim.getId(), ref);
168	        if (!claim.getLines().isEmpty() && amount.compareTo(claim.getAmount()) != 0) {
169	            throw new ClaimLinedAmountException();
170	        }
171	        claim.setAmount(amount);
172	        claim.setRef(ref);
173	        claim.setTags(tagged);
174	        claim.setCorrects(corrects);
175	        claim.setDate(on);
176	        claim.setNote(note);
177	        claim.setLockedBy(null);
178	        claim.setEditedBy(user.strip());
179	        Claim saved = claims.saveAndFlush(claim);
180	        record("CLAIM_EDITED", sheetId, user, person, saved);
181	        keepTags(sheetId, saved);
182	        rollup.recordChanges(sheetId, user, before);
183	        return saved;
184	    }
185	
186	    /**
187	     * Open a claim's editor: the claim is locked for every other user until the editor is saved or
188	     * cancelled, or the sheet's today changes. A claim that cannot be edited (not DRAFT, or due inside a
189	     * closed period), or one another user's editor already locks, is refused and takes no lock.
190	     */
191	    @Transactional
192	    public Claim lock(String sheetId, String user, Long id) {
193	        // Locking the sheet first, so two users opening the same claim's editor at once take turns.
194	        sheets.lockForNumbering(sheetId);
195	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
196	        if (claim.getStatus() != ClaimStatus.DRAFT) throw new ClaimStatusRefusedException();
197	        refuseIfClosed(sheetId, claim.getDueBy());
198	        if (claim.isLockedAgainst(user)) throw new ClaimLockedException();
199	        claim.setLockedBy(user.strip());
200	        return claims.saveAndFlush(claim);
201	    }
202	
203	    /** Cancel a claim's editor: the user's own lock on it is released; another user's is left as it is. */
204	    @Transactional
205	    public Claim unlock(String sheetId, String user, Long id) {
206	        sheets.lockForNumbering(sheetId);
207	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
208	        if (claim.getLockedBy() == null || claim.isLockedAgainst(user)) return claim;
209	        claim.setLockedBy(null);
210	        return claims.saveAndFlush(claim);
211	    }
212	
213	    @Transactional
214	    public Claim changeStatus(String sheetId, String user, Long id, ClaimStatus next) {
215	        return changeStatus(sheetId, user, id, next, null);
216	    }
217	
218	    /**
219	     * Settle a claim as part of a bulk settle: by the rules of settling one, then given the bulk's
220	     * batch number, the sheet's next one when the bulk has none yet (its first claim settled).
221	     */
222	    @Transactional
223	    public Claim settleInBatch(String sheetId, String user, Long id, Integer batch) {
224	        Claim claim = changeStatus(sheetId, user, id, ClaimStatus.SETTLED, null);
225	        claim.setSettleBatch(batch != null ? batch : sheets.lockForNumbering(sheetId).nextSettleBatch());
226	        return claims.saveAndFlush(claim);
227	    }
228	
229	    /**
230	     * Settle a claim as of a date on or before the sheet's today, by the rules of settling one, its due
231	     * fixed at the figure given (its due as it stood at the end of that date, see
232	     * {@link ClaimSettleAsOfService}); its settle record names the date.
233	     */
234	    @Transactional
235	    public Claim settleAsOf(String sheetId, String user, Long id, LocalDate on, BigDecimal figure) {
236	        if (on.isAfter(sheets.today(sheetId))) throw new ClaimSettleDateException();
237	        return changeStatus(sheetId, user, id, ClaimStatus.SETTLED, null, false, new AsOf(on, figure));
238	    }
239	
240	    /** A settle as of a date: the date and the claim's due as it stood at its end. */
241	    private record AsOf(LocalDate on, BigDecimal figure) {}
242	
243	    /** Void a claim; while the sheet's list of void reasons is not empty, only with a reason on it. */
244	    @Transactional
245	    public Claim voidClaim(String sheetId, String user, Long id, String reason) {
246	        return changeStatus(sheetId, user, id, ClaimStatus.VOID, reason);
247	    }
248	
249	    private Claim changeStatus(String sheetId, String user, Long id, ClaimStatus next, String reason) {
250	        return changeStatus(sheetId, user, id, next, reason, false);
251	    }
252	
253	    /**
254	     * Part-settle an OPEN claim: split the amount off it as {@link #split} does, then settle the new claim
255	     * by the user as settling one does (PENDING when over the clerk limit). The four-eyes rule and the proof
256	     * rule are judged on the original claim (its due before the split), not the new one the user opened; a
257	     * refusal of the split or the settle refuses the whole and changes nothing.
258	     */
259	    @Transactional
260	    public Split partSettle(String sheetId, String user, Long id, BigDecimal amount) {
261	        sheets.lockForNumbering(sheetId);
262	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
263	        if (claim.getStatus() != ClaimStatus.OPEN) throw new ClaimStatusRefusedException();
264	        if (!settings.mayDo(sheetId, user, "settle")) throw new ClaimNotPermittedException();
265	        if (claim.isOpenedOrEditedBy(user)) throw new ClaimSettledByOpenerException();
266	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
267	        refuseUnproved(sheetId, person, claim, chargedFigureOf(sheetId, person, claim));
268	        Split split = split(sheetId, user, id, amount);
269	        Claim settled = changeStatus(sheetId, user, split.split().getId(), ClaimStatus.SETTLED, null, true);
270	        return new Split(split.original(), settled);
271	    }
272	
273	    private Claim changeStatus(String sheetId, String user, Long id, ClaimStatus next, String reason,
274	            boolean judgedOnOriginal) {
275	        return changeStatus(sheetId, user, id, next, reason, judgedOnOriginal, null);
276	    }
277	
278	    private Claim changeStatus(String sheetId, String user, Long id, ClaimStatus next, String reason,
279	            boolean judgedOnOriginal, AsOf asOf) {
280	        // Settling takes the sheet's next number, locking the sheet first so the claim is read only
281	        // once no other settle on the sheet is under way; a refusal rolls the number back.
282	        Sheet numbering = next == ClaimStatus.SETTLED ? sheets.lockForNumbering(sheetId) : null;
283	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
284	        String action = switch (next) {
285	            case OPEN -> "open";
286	            case SETTLED -> "settle";
287	            case VOID -> "void";
288	            default -> throw new ClaimStatusRefusedException();
289	        };
290	        if (!settings.mayDo(sheetId, user, action)) throw new ClaimNotPermittedException();
291	        boolean voidingSettled = next == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED;
292	        if (voidingSettled) refuseVoidOfSettled(sheetId, user, claim);
293	        else if (!claim.getStatus().canBecome(next)) {
294	            throw new ClaimStatusRefusedException();
295	        }
296	        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) {
297	            throw new ClaimDeferredException();
298	        }
299	        if (next == ClaimStatus.SETTLED && !judgedOnOriginal && claim.isOpenedOrEditedBy(user)) {
300	            throw new ClaimSettledByOpenerException();
301	        }
302	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
303	        if (next == ClaimStatus.OPEN && person.flagOn(sheets.today(sheetId)) != null
304	                && settings.roleOf(sheetId, user) != Role.STEWARD) {
305	            throw new ClaimFlaggedException();
306	        }
307	        // Settling freezes the late charge of the moment (as of a date: of the end of that date) into the settled due.
308	        BigDecimal settling = next != ClaimStatus.SETTLED ? null
309	                : asOf != null ? asOf.figure() : chargedFigureOf(sheetId, person, claim);
310	        if (next == ClaimStatus.SETTLED && !judgedOnOriginal) refuseUnproved(sheetId, person, claim, settling);
311	        BigDecimal opening = next == ClaimStatus.OPEN ? chargedFigureOf(sheetId, person, claim) : null;
312	        if (next == ClaimStatus.OPEN) refuseUnnoted(sheetId, claim, opening);
313	        if (next == ClaimStatus.SETTLED && overClerkLimit(sheetId, user, person, claim, settling)) next = ClaimStatus.PENDING;
314	        String voidReason = next == ClaimStatus.VOID ? voidReasons.reasonForVoid(sheetId, reason) : null;
315	        RollupService.Snapshot before = rollup.snapshot(sheetId);
316	        refuseIfClosed(sheetId, claim.getDueBy());
317	        if (next == ClaimStatus.OPEN) refuseOverCap(sheetId, claim);
318	        if (next == ClaimStatus.OPEN) refuseOverMaxOpen(sheetId, claim);
319	        if (next == ClaimStatus.OPEN && overReviewThreshold(sheetId, claim, opening)) next = ClaimStatus.REVIEW;
320	        switch (next) {
321	            case OPEN -> claim.setOpenedBy(user.strip());
322	            case REVIEW -> {
323	                claim.setOpenedBy(user.strip());
324	                claim.setReviewOn(sheets.today(sheetId));
325	            }
326	            case SETTLED -> {
327	                numberUnlessNumbered(numbering, claim);
328	                claim.setSettledDue(settling);
329	                claim.setSettleBatch(null);
330	            }
331	            case PENDING -> {
332	                claim.setSettleBatch(null);
333	                claim.setPendingOn(sheets.today(sheetId));
334	            }
335	            case VOID -> claim.setVoidReason(voidReason);
336	            default -> {}
337	        }
338	        claim.setStatus(next);
339	        logStatus(sheetId, user, person, claim);
340	        Claim saved = claims.saveAndFlush(claim);
341	        String event = switch (next) {
342	            case OPEN -> "CLAIM_OPENED";
343	            case REVIEW -> "CLAIM_REVIEW";
344	            case PENDING -> "CLAIM_PENDING";
345	            case SETTLED -> "CLAIM_SETTLED";
346	            case VOID -> "CLAIM_VOIDED";
347	            case DRAFT, DELETED -> throw new IllegalStateException();
348	        };
349	        String due = next == ClaimStatus.SETTLED
350	                ? " due=" + (saved.getSettledDue() == null ? "n/a" : saved.getSettledDue().setScale(2).toPlainString())
351	                : voidingSettled ? " reversed=" + figureText(saved.getSettledDue())
352	                : "";
353	        if (voidReason != null) due += " reason=" + voidReason;
354	        if (next == ClaimStatus.SETTLED && asOf != null) due += " on=" + asOf.on();
355	        record(event, sheetId, user, person, saved, saved.getNumber(), due);
356	        if (next == ClaimStatus.SETTLED) notifyWatchers(sheetId, user, person, saved);
357	        rollup.recordChanges(sheetId, user, before);
358	        return saved;
359	    }
360	
361	    /**
362	     * Delete a DRAFT claim: DELETED, it counts nowhere and cannot be edited, opened or voided until restored.
363	     * Refused for a claim in any other status, one another user's editor locks, or one due inside a closed period.
364	     */
365	    @Transactional
366	    public Claim delete(String sheetId, String user, Long id) {
367	        // The snapshot locks the sheet first, so the claim is read once no other change is under way.
368	        RollupService.Snapshot before = rollup.snapshot(sheetId);
369	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
370	        if (!claim.getStatus().canBecome(ClaimStatus.DELETED)) throw new ClaimStatusRefusedException();
371	        if (claim.isLockedAgainst(user)) throw new ClaimLockedException();
372	        refuseIfClosed(sheetId, claim.getDueBy());
373	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
374	        claim.setLockedBy(null);
375	        claim.setStatus(ClaimStatus.DELETED);
376	        logStatus(sheetId, user, person, claim);
377	        Claim saved = claims.saveAndFlush(claim);
378	        record("CLAIM_DELETED", sheetId, user, person, saved);
379	        rollup.recordChanges(sheetId, user, before);
380	        return saved;
381	    }
382	
383	    /**
384	     * Restore a DELETED claim to DRAFT, on the same sheet's today it was deleted. Refused for a claim in any
385	     * other status, on a later day, or for one due inside a closed period.
386	     */
387	    @Transactional
388	    public Claim restore(String sheetId, String user, Long id) {
389	        // The snapshot locks the sheet first, so the claim is read once no other change is under way.
390	        RollupService.Snapshot before = rollup.snapshot(sheetId);
391	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
392	        if (claim.getStatus() != ClaimStatus.DELETED) throw new ClaimStatusRefusedException();
393	        if (!sheets.today(sheetId).equals(claim.deletedOn())) throw new ClaimRestoreWindowException();
394	        refuseIfClosed(sheetId, claim.getDueBy());
395	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
396	        claim.setStatus(ClaimStatus.DRAFT);
397	        logStatus(sheetId, user, person, claim);
398	        Claim saved = claims.saveAndFlush(claim);
399	        record("CLAIM_RESTORED", sheetId, user, person, saved);
400	        rollup.recordChanges(sheetId, user, before);
401	        return saved;
402	    }
403	
404	    /**
405	     * A steward other than its opener or last editor approves a PENDING claim: SETTLED, its due fixed at
406	     * its live due now, given the sheet's next number.
407	     */
408	    @Transactional
409	    public Claim approve(String sheetId, String user, Long id) {
410	        // Numbering locks the sheet first, so the claim is read once no other change is under way.
411	        Sheet numbering = sheets.lockForNumbering(sheetId);
412	        RollupService.Snapshot before = rollup.snapshot(sheetId);
413	        Claim claim = pendingForSteward(sheetId, user, id);
414	        if (claim.isOpenedOrEditedBy(user)) throw new ClaimApprovedByOpenerException();
415	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
416	        refuseIfClosed(sheetId, claim.getDueBy());
417	        BigDecimal settling = chargedFigureOf(sheetId, person, claim);
418	        refuseUnproved(sheetId, person, claim, settling);
419	        numberUnlessNumbered(numbering, claim);
420	        claim.setSettledDue(settling);
421	        claim.setStatus(ClaimStatus.SETTLED);
422	        logStatus(sheetId, user, person, claim);
423	        Claim saved = claims.saveAndFlush(claim);
424	        record("CLAIM_APPROVED", sheetId, user, person, saved, saved.getNumber(), " due="
425	                + (saved.getSettledDue() == null ? "n/a" : saved.getSettledDue().setScale(2).toPlainString()));
426	        notifyWatchers(sheetId, user, person, saved);
427	        rollup.recordChanges(sheetId, user, before);
428	        return saved;
429	    }
430	
431	    /**
432	     * A steward reviews a REVIEW claim: OPEN, with no number until settled, still opened by the user who
433	     * opened it. Refused for anyone else, a claim in any other status, or one due inside a closed period.
434	     */
435	    @Transactional
436	    public Claim review(String sheetId, String user, Long id) {
437	        // The snapshot locks the sheet first, so the claim is read once no other change is under way.
438	        RollupService.Snapshot before = rollup.snapshot(sheetId);
439	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
440	        if (claim.getStatus() != ClaimStatus.REVIEW) throw new ClaimStatusRefusedException();
441	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
442	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
443	        refuseIfClosed(sheetId, claim.getDueBy());
444	        refuseOverCap(sheetId, claim);
445	        claim.setStatus(ClaimStatus.OPEN);
446	        logStatus(sheetId, user, person, claim);
447	        Claim saved = claims.saveAndFlush(claim);
448	        record("CLAIM_REVIEWED", sheetId, user, person, saved, null, "");
449	        record("CLAIM_OPENED", sheetId, user, person, saved);
450	        rollup.recordChanges(sheetId, user, before);
451	        return saved;
452	    }

