519	    /**
520	     * A steward re-dates an OPEN or PENDING claim. Its due-by stays as it was fixed and a figure bound by a
521	     * statement stays bound; its period, which follows its due-by, stays too. A claim not yet settled has
522	     * no number to keep; while the sheet numbers by period and one numbered when opened was numbered within
523	     * another period, it takes the next number of its due-by's
524	     * period, its old number never given again. Refused for anyone else, a claim in any other status, one
525	     * due inside a closed period, or a new date after its person's retirement date.
526	     */
527	    @Transactional
528	    public Claim redate(String sheetId, String user, Long id, LocalDate date) {
529	        // Numbering locks the sheet first, so the claim is read once no other change is under way.
530	        Sheet numbering = sheets.lockForNumbering(sheetId);
531	        RollupService.Snapshot before = rollup.snapshot(sheetId);
532	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
533	        if (!claim.getStatus().isOpen()) throw new ClaimStatusRefusedException();
534	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
535	        refuseIfClosed(sheetId, claim.getDueBy());
536	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
537	        if (!person.mayClaimOn(date)) throw new PersonRetiredException();
538	        LocalDate old = claim.getDate();
539	        String oldPeriod = claim.getNumberPeriod() != null ? claim.getNumberPeriod() : periodOn(sheetId, claim.getDueBy());
540	        claim.setDate(date);
541	        if (claim.getNumber() != null && numbering.numbersByPeriod()
542	                && !oldPeriod.equals(periodOn(sheetId, claim.getDueBy()))) {
543	            if (claim.getNumberPeriod() != null) {
544	                claims.retireNumberWithin(sheetId, claim.getNumberPeriod(), claim.getNumberSeq());
545	            }
546	            number(numbering, claim);
547	        }
548	        Claim saved = claims.saveAndFlush(claim);
549	        record("CLAIM_REDATED", sheetId, user, person, saved, saved.getNumber(), " old=" + old + " new=" + date);
550	        rollup.recordChanges(sheetId, user, before);
551	        return saved;
552	    }
