618	    /**
619	     * Reassign a claim by the rules above; a bulk move ({@code bulk}) takes a claim already its new
620	     * person's as moved to them again rather than refusing it.
621	     */
622	    @Transactional
623	    public Claim reassign(String sheetId, String user, Long id, Long toPersonId, boolean bulk) {
624	        // Numbering locks the sheet first, so the claim is read once no other change is under way.
625	        Sheet numbering = sheets.lockForNumbering(sheetId);
626	        RollupService.Snapshot before = rollup.snapshot(sheetId);
627	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
628	        ClaimStatus status = claim.getStatus();
629	        if (status != ClaimStatus.DRAFT && !status.isOpen()) throw new ClaimStatusRefusedException();
630	        if (!settings.mayDo(sheetId, user, "reassign")) throw new ClaimNotPermittedException();
631	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
632	        Person to = people.findByIdAndSheetId(toPersonId, sheetId).orElseThrow(PersonNotFoundException::new);
633	        if (!bulk && from.getId().equals(to.getId())) throw new ClaimReassignRefusedException();
634	        refuseIfClosed(sheetId, claim.getDueBy());
635	        if (!to.mayClaimOn(claim.getDate())) throw new PersonRetiredException();
636	        claim.unstate(sheets.today(sheetId));
637	        claim.moveTo(to.getId(), claims.nextListed());
638	        if (claim.getNumber() != null) {
639	            if (claim.getNumberPeriod() != null) {
640	                claims.retireNumberWithin(sheetId, claim.getNumberPeriod(), claim.getNumberSeq());
641	            }
642	            number(numbering, claim);
643	        }
644	        Claim saved = claims.saveAndFlush(claim);
645	        record("CLAIM_REASSIGNED", sheetId, user, to, saved, saved.getNumber(),
646	                " from=" + from.getName() + " to=" + to.getName());
647	        rollup.recordChanges(sheetId, user, before);
648	        return saved;
