654	    /**
655	     * Split an amount (more than 0.00 and less than its amount) off an OPEN claim, by a user whose role may
656	     * open a claim. The claim keeps the rest of its amount and loses any figure a statement bound it to; the
657	     * new claim is OPEN with the split-off amount, the same date and note, no number until settled, opened
658	     * by the user, with its due-by fixed now from the terms in force on the date, and names the original's
659	     * number as split from, a late entry when its due-by falls in a soft-closed period. Refused for a claim
660	     * not OPEN, a deferred one, or one due inside a closed period (judged by the original alone).
661	     */
662	    @Transactional
663	    public Split split(String sheetId, String user, Long id, BigDecimal amount) {
664	        // The snapshot locks the sheet first, so the claim is read once no other change is under way.
665	        RollupService.Snapshot before = rollup.snapshot(sheetId);
666	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
667	        if (claim.getStatus() != ClaimStatus.OPEN) throw new ClaimStatusRefusedException();
668	        if (claim.isDeferredOn(sheets.today(sheetId))) throw new ClaimDeferredException();
669	        if (!settings.mayDo(sheetId, user, "open")) throw new ClaimNotPermittedException();
670	        refuseIfClosed(sheetId, claim.getDueBy());
671	        if (amount.signum() <= 0 || amount.compareTo(claim.getAmount()) >= 0) throw new ClaimSplitRefusedException();
672	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
673	        LocalDate on = claim.getDate();
674	        claim.setAmount(claim.getAmount().subtract(amount));
675	        claim.unstate(sheets.today(sheetId));
676	        Claim original = claims.saveAndFlush(claim);
677	        int terms = termsOf(sheetId, person, sheets.today(sheetId));
678	        LocalDate dueBy = holidays.businessDaysAfter(sheetId, on, terms);
679	        Claim split = new Claim(sheetId, person.getId(), amount, on, original.getNote(), dueBy, terms);
680	        split.setSplitFrom(original.getNumber());
681	        split.setTags(original.getTags());
682	        split.setLateEntry(periods.softClosedOn(sheetId, dueBy));
683	        split.setOpenedBy(user.strip());
684	        split.setEditedBy(original.getEditedBy());
685	        split.setStatus(ClaimStatus.OPEN);
686	        split = claims.saveAndFlush(split);
687	        logStatus(sheetId, user, person, split);
688	        split = claims.saveAndFlush(split);
689	        record("CLAIM_SPLIT", sheetId, user, person, original, original.getNumber(),
690	                " into=" + (split.getNumber() == null ? "" : split.getNumber()));
691	        record("CLAIM_OPENED", sheetId, user, person, split);
692	        rollup.recordChanges(sheetId, user, before);
693	        return new Split(original, split);
694	    }
