871	     * Refuse settling or approving a claim with no proofs whose due is above the proof threshold in force on
872	     * its date (its person's grade's then when set, else the sheet's); a due of n/a is within any, and no
873	     * threshold means none is needed. While the sheet has proof kinds, it needs a proof of each listed kind instead.
874	     */
875	    private void refuseUnproved(String sheetId, Person person, Claim claim, BigDecimal due) {
876	        if (due == null) return;
877	        List<String> kinds = settings.proofKinds(sheetId);
878	        boolean proved = kinds.isEmpty() ? claim.getProofs() > 0 : kinds.stream().allMatch(k -> claim.proofsOf(k) > 0);
879	        if (proved) return;
880	        BigDecimal threshold = settings.proofThresholdFor(sheetId, person.gradeOn(claim.getDate()), claim.getDate());
881	        if (threshold != null && due.compareTo(threshold) > 0) throw new ClaimProofRequiredException();
882	    }
