930	    /**
931	     * Give a claim its number: FY&lt;year&gt;-&lt;n&gt;, the next in the fiscal year its due-by falls in
932	     * (by the sheet's fiscal start month) after the last given in that year anywhere in the sheet's tree
933	     * (its topmost ancestor and every descendant of that), or while the sheet numbers by period, the next
934	     * within the period its due-by falls in (in no period: the next in the sheet's X sequence).
935	     */
936	    private void number(Sheet sheet, Claim claim) {
937	        if (!sheet.numbersByPeriod()) {
938	            int year = fiscalYearOf(sheet, claim.getDueBy() != null ? claim.getDueBy() : claim.getDate());
939	            claim.setFiscalNumber(year, sheets.nextFiscalNumberInTree(sheet.getId(), year));
940	            return;
941	        }
942	        String period = periodOn(sheet.getId(), claim.getDueBy());
943	        claim.setNumberWithin(period, claims.lastNumberWithin(sheet.getId(), period) + 1);
944	    }
