946	    /** The fiscal year the date falls in, by the calendar year of its first day (the sheet's start month). */
947	    private static int fiscalYearOf(Sheet sheet, LocalDate date) {
948	        return date.getMonthValue() >= sheet.getFiscalStartMonth() ? date.getYear() : date.getYear() - 1;
949	    }
