952	     * The terms a claim of the person created on the day (the sheet's today then) is fixed with: their own
953	     * terms in force that day, else those of the grade they had that day, else the sheet's that day. Its
954	     * due-by is the terms-th business day after its date (skipping weekends and the sheet's holidays).
955	     */
956	    private int termsOf(String sheetId, Person person, LocalDate on) {
957	        Integer own = person.termsOn(on);
958	        return own != null ? own : settings.termsFor(sheetId, person.gradeOn(on), on);
959	    }
