962	     * Refuse to open a claim whose due-by falls in a period with a cap when its person already has that
963	     * many OPEN or PENDING claims due inside the period.
964	     */
965	    /** Refuse opening a claim whose person already has the sheet's maximum of OPEN or PENDING claims. */
966	    private void refuseOverMaxOpen(String sheetId, Claim claim) {
967	        Integer max = settings.maxOpen(sheetId);
968	        if (max == null) return;
969	        long open = claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, claim.getPersonId()).stream()
970	                .filter(c -> !c.getId().equals(claim.getId()))
971	                .filter(c -> c.getStatus() == ClaimStatus.OPEN || c.getStatus() == ClaimStatus.PENDING)
972	                .count();
973	        if (open >= max) throw new ClaimMaxOpenReachedException();
974	    }
