982	                .filter(c -> !c.getId().equals(claim.getId()))
983	                .filter(c -> c.getStatus() == ClaimStatus.OPEN || c.getStatus() == ClaimStatus.PENDING)
984	                .filter(c -> period.contains(c.getDueBy()))
985	                .count();
