997	    /**
998	     * A claim's figure now: the due fixed when it was settled, else the due bound by its person's last
999	     * statement (late charge and floor included), else its rate figure (no floor, no charge); null when it
1000	     * has none.
1001	     */
1002	    public BigDecimal figureOf(String sheetId, Person person, Claim claim) {
1003	        if (claim.getSettledDue() != null) return claim.getSettledDue();
1004	        if (claim.isBound()) return claim.getStatedDue();
1005	        return dueOf(sheetId, person, claim);
