1020	    /**
1021	     * How many OPEN and PENDING claims of people on the grade (the one in force on the claim's date) would show
1022	     * a different due were the percent the grade's rate on every date, and the sum of new minus current dues
1023	     * (a due of n/a counts as 0). A claim bound by a statement does not change. Nothing is stored.
1024	     */
1025	    @Transactional(readOnly = true)
1026	    public RatePreview previewRate(String sheetId, String grade, BigDecimal pct) {
1027	        int count = 0;
1028	        BigDecimal diff = BigDecimal.ZERO.setScale(2);
1029	        Map<Long, Person> byId = new HashMap<>();
1030	        for (Person p : people.findBySheetIdOrderByPositionAscIdAsc(sheetId)) byId.put(p.getId(), p);
1031	        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
1032	            if (!claim.getStatus().isOpen() || claim.isBound()) continue;
1033	            Person person = byId.get(claim.getPersonId());
1034	            if (person == null || !grade.equals(person.gradeOn(claim.getDate()))) continue;
1035	            BigDecimal current = chargedFigureOf(sheetId, person, claim);
1036	            BigDecimal figure = claim.getAmount().multiply(pct).movePointLeft(2).setScale(2, roundingOf(sheetId, claim));
1037	            BigDecimal next = charged(sheetId, person, claim, figure);
1038	            BigDecimal was = current == null ? BigDecimal.ZERO.setScale(2) : current;
1039	            BigDecimal now = next == null ? BigDecimal.ZERO.setScale(2) : next;
1040	            if (current == null || now.compareTo(was) != 0) {
1041	                count++;
1042	                diff = diff.add(now.subtract(was));
1043	            }
1044	        }
1045	        return new RatePreview(count, diff.setScale(2));
1046	    }
