1048	    /**
1049	     * The claim's due with the figure given: floored, with its late charge on the floored figure while overdue; a settled due as
1050	     * fixed, a due bound by a statement as bound.
1051	     */
1052	    private BigDecimal charged(String sheetId, Person person, Claim claim, BigDecimal figure) {
1053	        if (claim.getSettledDue() != null) return claim.getSettledDue();
1054	        if (claim.isBound()) return claim.getStatedDue();
1055	        return LateCharge.withCharge(claim, floored(sheetId, claim, figure), sheets.today(sheetId),
1056	                graceOf(sheetId, person, claim), d -> settings.latePctOn(sheetId, d), roundingOf(sheetId, claim));
1057	    }
