1059	    /** The grace days of the person's grade on the claim's date, in force on it; 0 when none. */
1060	    private int graceOf(String sheetId, Person person, Claim claim) {
1061	        return settings.graceOn(sheetId, person.gradeOn(claim.getDate()), claim.getDate());
1062	    }
