1064	    /** The due at least the sheet's floor in force on the claim's date, unless a correction; null when none. */
1065	    private BigDecimal floored(String sheetId, Claim claim, BigDecimal due) {
1066	        if (due == null || claim.isCorrection()) return due;
1067	        return due.max(settings.floorOn(sheetId, claim.getDate()));
1068	    }
