1070	    /** How the claim's live figures round: by its date, or a correction's by its corrected claim's ({@link Rounding}). */
1071	    private RoundingMode roundingOf(String sheetId, Claim claim) {
1072	        LocalDate basis = Rounding.basisOf(claim,
1073	                Rounding.datesByNumber(claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, claim.getPersonId())));
1074	        return Rounding.of(basis, settings.roundingOn(sheetId, basis), settings.policyDate(sheetId), sheets.today(sheetId));
1075	    }
