1077	    /**
1078	     * A claim's rate figure: its amount times the rate on its date of its person's grade in force on it (of those
1079	     * that apply to the claim: no forward-only rate saved after it was added), rounded to cents as {@link Rounding}
1080	     * has it, with no floor; null with no rate.
1081	     */
1082	    private BigDecimal dueOf(String sheetId, Person person, Claim claim) {
1083	        RoundingMode rounding = roundingOf(sheetId, claim);
1084	        return rates.onFor(sheetId, person.gradeOn(claim.getDate()), claim.getDate(), claim.getAdded())
1085	                .map(Rate::getPct)
1086	                .map(pct -> claim.getAmount().multiply(pct).movePointLeft(2).setScale(2, rounding))
1087	                .orElse(null);
1088	    }
