1090	    /** Log the status the claim now has: by the user on the sheet's today, with its due at this moment. */
1091	    private void logStatus(String sheetId, String user, Person person, Claim claim) {
1092	        claim.logStatus(user.strip(), sheets.today(sheetId), chargedFigureOf(sheetId, person, claim));
1093	    }
