1099	    /** A claim's audit line; one about a claim with a number has it, then any extra fields. */
1100	    private void record(String event, String sheetId, String user, Person person, Claim claim, String number,
1101	            String extra) {
1102	        audit.recordOnCommit(event + " sheet=" + sheetId + " by=" + user.strip() + " person=" + person.getName()
1103	                + " amount=" + claim.getAmount().setScale(2).toPlainString() + " date=" + claim.getDate()
1104	                + (number != null ? " number=" + number : "") + extra);
1105	    }
