1107	    /**
1108	     * Take a person's claims, as they arrive with them from another sheet, onto the sheet (locked for
1109	     * numbering by the caller): each loses what {@link Claim#transferTo} drops, and each that had a number
1110	     * takes the sheet's next, in the order they were opened (by the sheet's today each was first opened on,
1111	     * then in the order they were added). A correction, or a claim split off another, then names the
1112	     * number its claim was given. Their tags are kept among those used on the sheet.
1113	     */
1114	    @Transactional
1115	    public void receive(Sheet to, List<Claim> arriving) {
1116	        Map<Long, String> old = new HashMap<>();
1117	        for (Claim claim : arriving) {
1118	            old.put(claim.getId(), claim.getNumber());
1119	            claim.transferTo(to.getId(), claims.nextAdded());
1120	        }
1121	        claims.saveAllAndFlush(arriving);
1122	        numberAfresh(to, arriving, old);
1123	        for (Claim claim : arriving) keepTags(to.getId(), claim);
1124	        claims.saveAllAndFlush(arriving);
1125	    }
1126	
1127	    /**
1128	     * Number afresh, on the sheet (locked for numbering by the caller), the claims that had a number before
1129	     * ({@code oldNumbers}, by claim id): each takes the sheet's next, in the order they were opened (by the
1130	     * sheet's today each was first opened on, then in the order they were added). A correction, or a claim
1131	     * split off another, then names the number its claim was given.
1132	     */
1133	    @Transactional
1134	    public void numberAfresh(Sheet to, List<Claim> numbering, Map<Long, String> oldNumbers) {
1135	        List<Claim> numbered = numbering.stream().filter(c -> oldNumbers.get(c.getId()) != null)
1136	                .sorted(Comparator.comparing(Claim::openedOn,
1137	                        Comparator.nullsFirst(Comparator.naturalOrder()))
1138	                        .thenComparing(Claim::getId))
1139	                .toList();
1140	        Map<String, String> renumbered = new HashMap<>();
1141	        for (Claim claim : numbered) {
1142	            number(to, claim);
1143	            claims.saveAndFlush(claim);
1144	            renumbered.put(oldNumbers.get(claim.getId()), claim.getNumber());
1145	        }
1146	        for (Claim claim : numbering) {
1147	            if (claim.getCorrects() != null) {
1148	                claim.setCorrects(renumbered.getOrDefault(claim.getCorrects(), claim.getCorrects()));
1149	            }
1150	            if (claim.getSplitFrom() != null) {
1151	                claim.setSplitFrom(renumbered.getOrDefault(claim.getSplitFrom(), claim.getSplitFrom()));
1152	            }
1153	        }
1154	        claims.saveAllAndFlush(numbering);
1155	    }
