1170	    /** Refuse a reference (null: none) that a claim on the sheet other than this one (null: any) already carries. */
1171	    private void refuseIfRefUsed(String sheetId, Long self, String ref) {
1172	        if (ref == null) return;
1173	        claims.findBySheetIdAndRefKey(sheetId, Claim.refKeyOf(ref))
1174	                .filter(other -> !other.getId().equals(self))
1175	                .ifPresent(other -> { throw new DuplicateClaimRefException(); });
