1178	    /**
1179	     * Refuse a correction that names no SETTLED claim of its person by number, and a claim that names
1180	     * one but is not a correction. A correction may not exceed what remains of the claim it corrects: its
1181	     * amount less the corrections already made against it (VOID or DELETED ones, and this claim (null:
1182	     * none) itself, left out).
1183	     */
1184	    private void refuseUnlessCorrects(String sheetId, Long personId, Long self, BigDecimal amount, String corrects) {
1185	        if (amount.signum() >= 0) {
1186	            if (corrects != null) throw new CorrectionRefusedException();
1187	            return;
1188	        }
1189	        if (corrects == null) throw new CorrectionRefusedException();
1190	        List<Claim> ofPerson = claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId);
1191	        Claim target = ofPerson.stream()
1192	                .filter(c -> corrects.equals(c.getNumber()) && c.getStatus() == ClaimStatus.SETTLED)
1193	                .findFirst().orElseThrow(CorrectionRefusedException::new);
1194	        BigDecimal remaining = ofPerson.stream()
1195	                .filter(c -> corrects.equals(c.getCorrects()) && !c.getId().equals(self)
1196	                        && c.getStatus() != ClaimStatus.VOID && c.getStatus() != ClaimStatus.DELETED)
1197	                .map(Claim::getAmount)
1198	                .reduce(target.getAmount(), BigDecimal::add);
1199	        if (amount.negate().compareTo(remaining) > 0) throw new CorrectionRefusedException();
1200	    }
