    /** Swap the person with the one above or below them in the list. */
    @PostMapping("/{id}/move")
    public PersonView move(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable Long id,
