protected readonly pasteError = signal('');
/** How many lines the last paste put through; null before one, and while one runs. */
protected readonly pasteAdded = signal<number | null>(null);
protected readonly pasteForm = new FormGroup({
  text: new FormControl('', { nonNullable: true }),
});

/** The person's cut total in cents: their cuts across every pool they are a member of, added up. */
protected cutTotalOf(personId: number): number {
  return this.session.cutTotals().get(personId) ?? 0;
}

constructor() {
  this.pasteForm.valueChanges.subscribe(() => this.pasteError.set(''));
  this.importForm.valueChanges.subscribe(() => this.importError.set(''));
  this.form.valueChanges.subscribe(() => this.error.set(''));
  this.quickForm.valueChanges.subscribe(() => this.quickError.set(''));
  this.bulkGradeForm.valueChanges.subscribe(() => this.personError.set(null));
  effect(() => this.session.people.set(this.people().map((p) => ({ id: p.id, name: p.name, shown: this.shownName(p), retired: p.retired }))));
  effect(() => this.session.dueTotals.set(new Map(this.people().map((p) => [p.id, this.dueTotalCents(p)]))));
  effect(() => {
/**
 * Their timeline: a line per dated thing about them in date order, and on a date their grade changes, then
 * their claims, then holds, then retirements, then unretirements; lines of a kind on a date in text order.
 */
protected timelineOf(p: Person): string[] {
  const lines: { date: string; rank: number; text: string }[] = [];
  for (const g of p.grades) if (g.from !== null) lines.push({ date: g.from, rank: 0, text: `grade ${g.grade}` });
  for (const c of this.claimsOf(p.id)) lines.push({ date: c.date, rank: 1, text: `claim ${c.amount} ${c.status}` });
  for (const h of p.holds) {
    if (h.from !== null) lines.push({ date: h.from, rank: 2, text: h.to === null ? 'hold' : `hold to ${h.to}` });
  }
  for (const r of p.retirements) {
